// ── Scaled Dot-Product Attention — worked numeric example ──────
//
// We have 3 tokens with d_k=2 for illustration.
// In a real model, d_k = d_model / num_heads (e.g. 4096/32 = 128).

function softmax(arr) {
  const max = Math.max(...arr);           // numeric stability: subtract max
  const exps = arr.map(x => Math.exp(x - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

function dot(a, b) {
  return a.reduce((s, v, i) => s + v * b[i], 0);
}

// Q, K, V for 3 tokens (each a 2-dim vector for illustration)
const Q = [[1, 0], [0, 1], [1, 1]];   // queries
const K = [[1, 0], [0, 1], [0, 0]];   // keys
const V = [[10, 0], [0, 10], [5, 5]]; // values
const dk = 2;  // query/key dimension

// Full attention for token 0 (no mask): score[j] = Q[0] · K[j] / sqrt(dk)
const scores0 = K.map(k => dot(Q[0], k) / Math.sqrt(dk));
console.log('Raw scores for token 0:', scores0.map(s => s.toFixed(3)));
// [ '0.707', '0.000', '0.000' ]   (1/√2, 0, 0)

const weights0 = softmax(scores0);
console.log('Attention weights:', weights0.map(w => w.toFixed(3)));
// [ '0.503', '0.248', '0.248' ]  — token 0 attends most to itself

const weightedSum = (w) => V[0].map((_, i) => w.reduce((s, wj, j) => s + wj * V[j][i], 0));
console.log('Output for token 0:', weightedSum(weights0).map(v => v.toFixed(2)));
// [ '6.28', '3.72' ]  — mostly V[0]=[10,0], blended with the others

// ── Causal mask: what a decoder-only LLM actually computes ────
// Token i may only see tokens 0..i. Future scores become -Infinity,
// so softmax gives them exactly zero weight.
for (let i = 0; i < Q.length; i++) {
  const scores = K.map((k, j) => (j <= i ? dot(Q[i], k) / Math.sqrt(dk) : -Infinity));
  console.log(`causal weights row ${i}:`, softmax(scores).map(w => w.toFixed(3)));
}
// row 0: [ '1.000', '0.000', '0.000' ]  — the first token can only see itself
// row 1: [ '0.330', '0.670', '0.000' ]
// row 2: [ '0.401', '0.401', '0.198' ]

// ── Why the sqrt(dk) scaling matters ──────────────────────────
// For random vectors, dot products grow like sqrt(dk). With dk = 64,
// raw scores of this size are typical:
const dkLarge = 64;
const raw = [24, 20, 2];
console.log('Unscaled softmax:', softmax(raw).map(s => s.toFixed(3)));
// [ '0.982', '0.018', '0.000' ]  — nearly one-hot: gradients to others vanish
console.log('Scaled softmax:  ', softmax(raw.map(s => s / Math.sqrt(dkLarge))).map(s => s.toFixed(3)));
// [ '0.599', '0.363', '0.038' ]  — divided by 8: a softer, trainable distribution

// ── Token counting heuristics ─────────────────────────────────
function estimateTokens(text) {
  const words = text.trim().split(/\s+/).length;
  return {
    byWords: Math.ceil(words / 0.75),   // 1 token ≈ 0.75 English words
    byChars: Math.ceil(text.length / 4) // 1 token ≈ 4 English characters
  };
}

const paragraph = 'The quick brown fox jumps over the lazy dog. '
  + 'This sentence is used to illustrate token counting.';
console.log('Estimated tokens:', estimateTokens(paragraph));
// { byWords: 23, byChars: 24 }  — heuristics only; use the model's tokenizer for billing

// ── Temperature sampling simulation ───────────────────────────
//
// Illustrates how temperature changes the probability distribution
// over the vocabulary before sampling.

function softmax(logits) {
  const max = Math.max(...logits);
  const exps = logits.map(x => Math.exp(x - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

// Toy vocabulary: 5 possible next tokens with raw logits
const tokens   = ['Paris', 'London', 'Berlin', 'Rome', 'Madrid'];
const logits   = [4.2, 2.8, 1.5, 0.9, 0.3];  // model's raw scores

function applyTemperature(logits, temperature) {
  if (temperature === 0) {
    // Greedy: one-hot at argmax
    const maxIdx = logits.indexOf(Math.max(...logits));
    return logits.map((_, i) => i === maxIdx ? 1.0 : 0.0);
  }
  return softmax(logits.map(l => l / temperature));
}

const temperatures = [0.0, 0.5, 1.0, 1.5];
for (const T of temperatures) {
  const probs = applyTemperature(logits, T);
  const label = T === 0 ? 'greedy' : `T=${T}`;
  console.log(`\n[${label}]`);
  tokens.forEach((t, i) => console.log(`  ${t.padEnd(8)} ${(probs[i]*100).toFixed(1)}%`));
}
// [greedy]   Paris 100%,   all others 0%
// [T=0.5]    Paris 93.7%,  London 5.7%,  Berlin 0.4%
// [T=1]      Paris 72.9%,  London 18.0%, Berlin 4.9%   (softmax of raw logits)
// [T=1.5]    Paris 57.4%,  London 22.6%, Berlin 9.5%   (flatter)

// ── Top-p (nucleus) sampling ───────────────────────────────────
function topPNucleus(probs, p) {
  // Sort tokens by probability descending, take smallest set summing to >= p
  const sorted = probs
    .map((prob, i) => ({ i, prob }))
    .sort((a, b) => b.prob - a.prob);

  let cumulative = 0;
  const nucleus = [];
  for (const item of sorted) {
    nucleus.push(item);
    cumulative += item.prob;
    if (cumulative >= p) break;
  }
  return nucleus;   // the sampler renormalises these and draws one
}

const probs1 = applyTemperature(logits, 1.0);
console.log('\nTop-p=0.9 nucleus:', topPNucleus(probs1, 0.9).map(({ i }) => tokens[i]));
// [ 'Paris', 'London' ]  — 72.9% + 18.0% = 90.9% already covers p = 0.9
console.log('Top-p=0.95 nucleus:', topPNucleus(probs1, 0.95).map(({ i }) => tokens[i]));
// [ 'Paris', 'London', 'Berlin' ]  — a larger p admits more of the tail

// ── Context budget check (limits are illustrative — they change often) ──
const CONTEXT_LIMITS = {
  'small-local-model':     8_192,
  'typical-api-model':   200_000,
  'long-context-model': 1_000_000,
};

function checkFitsInContext(text, model, reservedForOutput = 8_000) {
  const estimatedTokens = Math.ceil(text.length / 4);   // rough: ~4 chars per token
  const limit = CONTEXT_LIMITS[model];
  return {
    estimatedTokens,
    limit,
    fits: estimatedTokens + reservedForOutput <= limit,  // prompt AND answer share the window
    percentUsed: ((estimatedTokens / limit) * 100).toFixed(1) + '%'
  };
}

const longDoc = 'x'.repeat(400_000); // 400k chars ≈ 100k tokens
console.log(checkFitsInContext(longDoc, 'typical-api-model'));
// { estimatedTokens: 100000, limit: 200000, fits: true, percentUsed: '50.0%' }

// ── LLM parameter count estimation ────────────────────────────
// Simplified — ignores biases, norms, and GQA/SwiGLU details

function estimateParams({ vocabSize, dModel, numLayers, ffnMultiplier = 4, tiedEmbeddings = false }) {
  const embeddingParams = vocabSize * dModel;          // token embedding matrix

  // Per block: 4 attention matrices (Wq, Wk, Wv, Wo) + 2 FFN matrices
  const attnParams = 4 * dModel * dModel;
  const ffnParams  = 2 * dModel * (ffnMultiplier * dModel); // W1: d→4d, W2: 4d→d
  const perBlock   = attnParams + ffnParams;

  // Output head ("unembedding"); shares the embedding weights when tied
  const outputParams = tiedEmbeddings ? 0 : vocabSize * dModel;

  const total = embeddingParams + numLayers * perBlock + outputParams;
  return {
    embeddingParams: (embeddingParams / 1e6).toFixed(0) + 'M',
    perBlockParams:  (perBlock / 1e6).toFixed(1) + 'M',
    totalParams:     (total / 1e9).toFixed(2) + 'B'
  };
}

// Llama 3 8B approximation (untied embeddings)
console.log('Llama 3 8B:', estimateParams({ vocabSize: 128_000, dModel: 4096, numLayers: 32 }));
// { embeddingParams: '524M', perBlockParams: '201.3M', totalParams: '7.49B' }
// Real model: 8.03B — its SwiGLU FFN is wider (3 matrices, 14,336 hidden),
// while grouped-query attention makes Wk and Wv 4x smaller.

// GPT-2 small (tied embeddings)
console.log('GPT-2 small:', estimateParams({ vocabSize: 50_257, dModel: 768, numLayers: 12, tiedEmbeddings: true }));
// { embeddingParams: '39M', perBlockParams: '7.1M', totalParams: '0.12B' }
// Real model: 124M (adds 0.8M learned position embeddings, biases, norms)

// Chinchilla compute-optimal token count
function chinchillaTokens(numParams) {
  const tokens = numParams * 20;      // ~20 tokens per parameter (Hoffmann et al. 2022)
  return (tokens / 1e9).toFixed(0) + 'B tokens';
}

console.log('Chinchilla-optimal for 8B:', chinchillaTokens(8e9));
// '160B tokens' — Llama 3 8B used ~15T, about 94x more, to be cheaper to serve

// Training compute rule of thumb: ~6 FLOPs per parameter per token
const flops = 6 * 8e9 * 15e12;
console.log('Training FLOPs (8B params x 15T tokens):', flops.toExponential(1));
// '7.2e+23'
